import { type ReactElement, useCallback, useEffect } from "react";
import type { LayoutChangeEvent } from "react-native";
import Animated, {
	cancelAnimation,
	Extrapolation,
	interpolate,
	interpolateColor,
	useAnimatedStyle,
	useSharedValue,
	withTiming,
} from "react-native-reanimated";
import { useThemeColor } from "@registry/hooks/use-theme-color";
import { IconCheckmark1Small, IconMinusSmall } from "@registry/icons/central";
import { Icon } from "@registry/ui/icon";
import { useCheckboxPart } from "./checkbox.context";
import {
	CHECKBOX_FILL_RADIUS,
	CHECKBOX_GLYPH_TOKEN,
	CHECKBOX_INDICATOR_ANIMATION,
	CHECKBOX_INVALID_GLYPH_TOKEN,
	checkboxVariants,
	resolveCheckboxBorderTokens,
	resolveCheckboxFilled,
} from "./checkbox.variants";

/**
 * The square itself: its border, the fill behind it and the tick drawn on top.
 *
 * Internal — the checkbox renders one and there is nothing for a caller to
 * compose here that `isIndeterminate` does not already decide. It takes a file
 * of its own because it owns every animated value; keeping them in the root
 * would make the root a component that changes for two unrelated reasons.
 *
 * Three things move, off one shared progress, so they cannot drift out of step:
 *
 * - the **fill** fades and scales from the centre. A box is filled, not slid
 *   into, so it arrives from no edge. Its corner radius is fixed rather than
 *   animated — {@link CHECKBOX_FILL_RADIUS} keeps it concentric with the border
 *   at every scale, and the transform shrinks the rendered corner with it.
 * - the **tick** is clipped by a container whose width opens from the left, so
 *   the stroke is drawn on when ticking and taken back when unticking rather
 *   than faded up in place.
 * - the **border** interpolates from the field chrome to the fill's own colour,
 *   held back by `borderDelay` until the surface is near the edge — so it reads
 *   as the fill arriving at the border rather than as an outline changing on its
 *   own. A colour being interpolated cannot be a class, which is why this one is
 *   the only part of the box a `tv()` does not describe.
 *
 * The clip needs the box's width in points, and a `size-checkbox-*` class cannot
 * be read from JavaScript. It comes from the fill's own `onLayout` rather than a
 * table of numbers restating `tokens.css` — that layer is already exactly the
 * size the clip has to span.
 *
 * Reduce-motion takes Reanimated's default `System` policy here, deliberately
 * unlike `Spinner`. Under it `withTiming` completes instantly, which for a
 * checkbox is exactly right: the state change is the point and the travel is
 * decoration. A spinner had to opt out because its animation *is* the signal.
 */
export function CheckboxBox(): ReactElement {
	const { color, size, isChecked, isIndeterminate, isInvalid } = useCheckboxPart("Checkbox.Box");
	const isFilled = resolveCheckboxFilled({ isChecked, isIndeterminate });

	const progress = useSharedValue(isFilled ? 1 : 0);
	const boxWidth = useSharedValue(0);

	useEffect(() => {
		progress.value = withTiming(isFilled ? 1 : 0, { duration: CHECKBOX_INDICATOR_ANIMATION.durationMs });

		// Without this a box unmounted mid-toggle leaves its timing running.
		return () => cancelAnimation(progress);
	}, [isFilled, progress]);

	const handleLayout = useCallback(
		(event: LayoutChangeEvent) => {
			boxWidth.value = event.nativeEvent.layout.width;
		},
		[boxWidth]
	);

	const border = resolveCheckboxBorderTokens({ color, isInvalid });
	const restBorderColor = useThemeColor(border.rest) ?? "transparent";
	const activeBorderColor = useThemeColor(border.active) ?? "transparent";

	const boxStyle = useAnimatedStyle(() => ({
		borderColor: interpolateColor(
			interpolate(progress.value, [CHECKBOX_INDICATOR_ANIMATION.borderDelay, 1], [0, 1], Extrapolation.CLAMP),
			[0, 1],
			[restBorderColor, activeBorderColor]
		),
	}));

	const fillStyle = useAnimatedStyle(() => ({
		opacity: interpolate(progress.value, [0, 1], CHECKBOX_INDICATOR_ANIMATION.opacity),
		transform: [{ scale: interpolate(progress.value, [0, 1], CHECKBOX_INDICATOR_ANIMATION.scale) }],
	}));

	// Clamped, so the tick sits at zero width through the delay rather than being
	// extrapolated to a negative one.
	const tickStyle = useAnimatedStyle(() => ({
		width:
			boxWidth.value *
			interpolate(progress.value, [CHECKBOX_INDICATOR_ANIMATION.tickDelay, 1], [0, 1], Extrapolation.CLAMP),
	}));

	// Full width regardless of the clip in front of it, so the glyph stays on the
	// box's centre line while the clip opens instead of sliding across with it.
	const tickInnerStyle = useAnimatedStyle(() => ({ width: boxWidth.value }));

	const slots = checkboxVariants({ color, isFilled, isInvalid, size });
	// A colour that has to reach an SVG paint prop cannot be a class. See Theming.
	const glyphColor = useThemeColor(isInvalid ? CHECKBOX_INVALID_GLYPH_TOKEN : CHECKBOX_GLYPH_TOKEN[color]);

	return (
		<Animated.View className={slots.box()} style={boxStyle}>
			<Animated.View
				className={slots.indicator()}
				onLayout={handleLayout}
				// A fixed radius rather than an animated one: the fill has to stay
				// concentric with the border at every scale, and the value that
				// achieves that never changes. `scale` shrinks the rendered corner
				// along with the square, which is what keeps a half-grown fill
				// looking like a smaller version of the finished one.
				style={[{ borderRadius: CHECKBOX_FILL_RADIUS[size] }, fillStyle]}
			/>
			<Animated.View className={slots.tick()} style={tickStyle}>
				<Animated.View className={slots.tickInner()} style={tickInnerStyle}>
					<Icon
						className={slots.glyph()}
						color={glyphColor}
						icon={isIndeterminate ? IconMinusSmall : IconCheckmark1Small}
					/>
				</Animated.View>
			</Animated.View>
		</Animated.View>
	);
}
CheckboxBox.displayName = "DelacourUI.Checkbox.Box";

import { type ReactElement, type ReactNode, useCallback, useMemo } from "react";
import { View, type ViewProps } from "react-native";
import { useControllableState } from "@registry/hooks/use-controllable-state";
import { type CheckboxGroupContextValue, CheckboxGroupProvider } from "./checkbox.context";
import {
	type CheckboxAlignment,
	type CheckboxColor,
	type CheckboxSize,
	checkboxVariants,
	toggleCheckedValue,
} from "./checkbox.variants";

export type CheckboxGroupProps = Omit<ViewProps, "children"> & {
	/** The `value` of every checked child. Controlled. */
	checked?: string[];
	/** The values checked to begin with, while uncontrolled. */
	defaultChecked?: string[];
	/** Fired with the whole list every time a child is toggled. */
	onChecked?: (checked: string[]) => void;
	/** Defaults every child takes unless it names its own. */
	color?: CheckboxColor;
	size?: CheckboxSize;
	alignment?: CheckboxAlignment;
	isInvalid?: boolean;
	isDisabled?: boolean;
	className?: string;
	children?: ReactNode;
};

function CheckboxGroupRoot({
	checked,
	defaultChecked = EMPTY,
	onChecked,
	color,
	size,
	alignment,
	isInvalid,
	isDisabled,
	className,
	children,
	...props
}: CheckboxGroupProps): ReactElement {
	const [values, setValues] = useControllableState<string[]>({
		defaultValue: defaultChecked,
		onChange: onChecked,
		value: checked,
	});

	const toggle = useCallback((value: string) => setValues(toggleCheckedValue(values, value)), [setValues, values]);

	const context = useMemo<CheckboxGroupContextValue>(
		() => ({ alignment, checked: values, color, isDisabled, isInvalid, size, toggle }),
		[alignment, color, isDisabled, isInvalid, size, toggle, values]
	);

	return (
		<CheckboxGroupProvider value={context}>
			<View className={checkboxVariants().group({ className })} {...props}>
				{children}
			</View>
		</CheckboxGroupProvider>
	);
}

/**
 * A stable empty list, so an uncontrolled group does not seed its state from a
 * fresh array on every render.
 */
const EMPTY: string[] = [];

/**
 * The checked list for the checkboxes inside it, and the axes they share.
 *
 * State is one array of the children's `value`s: `checked={["email"]}` ticks the
 * box called `email`, and `onChecked` fires with the whole new list each time
 * one is toggled. Controlled or uncontrolled from the same hook — pass `checked`
 * to own it, or `defaultChecked` and let the group hold it.
 *
 * **The axes here are defaults, not overrides.** A child's own `color` or `size`
 * wins, and so does an explicit `isDisabled={false}` under a disabled group.
 * That is the opposite of `Input.Group`, and the difference is what each owns:
 * `Input.Group` *is* the box its field renders into, so the axes that draw one
 * can only have a single answer. A `Checkbox.Group` owns no box — it is a
 * wrapper supplying context, the same kind of thing as `Field`, and a control
 * overrides one of those.
 *
 * A plain `View`, with no role. A group of checkboxes is a container, and
 * announcing it as a control would put an element with no action in front of
 * every child. Lay them out any other way with a `className` —
 * `flex-row flex-wrap` for a row.
 *
 * @example
 * <Checkbox.Group checked={channels} onChecked={setChannels}>
 *   <Checkbox value="email">Email</Checkbox>
 *   <Checkbox value="sms">SMS</Checkbox>
 *   <Checkbox value="push">Push</Checkbox>
 * </Checkbox.Group>
 *
 * @example
 * <Checkbox.Group color="success" defaultChecked={["daily"]} size="lg">
 *   <Checkbox value="daily">Daily digest</Checkbox>
 *   <Checkbox color="danger" value="alerts">Incident alerts</Checkbox>
 * </Checkbox.Group>
 */
export const CheckboxGroup = Object.assign(CheckboxGroupRoot, {
	displayName: "DelacourUI.Checkbox.Group",
});

import type { ReactElement } from "react";
import { Text } from "@registry/ui/text";
import { useCheckboxPart } from "./checkbox.context";
import type { CheckboxLabelProps } from "./checkbox.types";
import { checkboxVariants, resolveCheckboxLabelColor, resolveCheckboxLabelSize } from "./checkbox.variants";

/**
 * The checkbox's text, inside the checkbox's own tap target.
 *
 * That is the whole reason this part exists next to `Field.Label`, which does
 * the same job a row away: this one sits inside the pressable, so tapping the
 * words toggles the box. Use `Field.Label` for a checkbox that sits beside its
 * name in a horizontal `Field`, and this one for a checkbox that carries its
 * own.
 *
 * Renders `Text.Label` and passes it a step and a colour, never a class for
 * either — the type scale belongs to the preset, and restating it here would be
 * a second definition of `Text.Label` that could drift from it. The `className`
 * carries layout alone. It turns danger with the box it names, so the pair reads
 * as one state.
 */
export function CheckboxLabel({ className, color, size, ...props }: CheckboxLabelProps): ReactElement {
	const { alignment, isInvalid, size: checkboxSize } = useCheckboxPart("Checkbox.Label");

	return (
		<Text.Label
			className={checkboxVariants({ alignment }).label({ className })}
			color={color ?? resolveCheckboxLabelColor(isInvalid)}
			size={size ?? resolveCheckboxLabelSize(checkboxSize)}
			{...props}
		/>
	);
}
CheckboxLabel.displayName = "DelacourUI.Checkbox.Label";

import { createContext, type ReactElement, type ReactNode, use } from "react";
import type { CheckboxAlignment, CheckboxColor, CheckboxSize } from "./checkbox.variants";

export type CheckboxContextValue = {
	/** What a ticked box means. */
	color: CheckboxColor;
	/** Size of the box, its glyph and the label beside it. */
	size: CheckboxSize;
	/** Which side of the label the box sits on. */
	alignment: CheckboxAlignment;
	/** Whether the box is ticked. */
	isChecked: boolean;
	/** Whether the box reports a mixed state rather than a settled one. */
	isIndeterminate: boolean;
	/** Whether the box reports an invalid value. */
	isInvalid: boolean;
	/** Whether the box is unavailable. */
	isDisabled: boolean;
};

export type CheckboxGroupContextValue = {
	/** The `value` of every checked child. */
	checked: readonly string[];
	/** Flips one child's value in that list. */
	toggle: (value: string) => void;
	/** Defaults a child takes when it names none of its own. */
	color?: CheckboxColor;
	size?: CheckboxSize;
	alignment?: CheckboxAlignment;
	isInvalid?: boolean;
	isDisabled?: boolean;
};

const CheckboxContext = createContext<CheckboxContextValue | null>(null);

const CheckboxGroupContext = createContext<CheckboxGroupContextValue | null>(null);

/**
 * Supplies the enclosing checkbox's axes and state to its subtree.
 *
 * Lives in its own module, importing nothing but React and a type, so a part can
 * read it without importing `./checkbox`. That import would close a cycle, and
 * Metro serves a partially initialised module for a cycle — leaving the context
 * `undefined` at import time and red-boxing the app on a cold start.
 */
export function CheckboxProvider({
	value,
	children,
}: {
	value: CheckboxContextValue;
	children: ReactNode;
}): ReactElement {
	return <CheckboxContext value={value}>{children}</CheckboxContext>;
}
CheckboxProvider.displayName = "DelacourUI.Checkbox.Provider";

/** The enclosing checkbox's context, or null outside a `<Checkbox>`. */
export function useCheckboxContext(): CheckboxContextValue | null {
	return use(CheckboxContext);
}

/**
 * Reads the enclosing checkbox's axes and state.
 *
 * Lets a custom child style itself to match without the checkbox having to pass
 * props down through every slot. Throws outside a `<Checkbox>` — use
 * {@link useCheckboxContext} where the enclosing checkbox is optional.
 */
export function useCheckbox(): CheckboxContextValue {
	const context = useCheckboxContext();
	if (!context) {
		throw new Error("useCheckbox must be called inside a <Checkbox>.");
	}
	return context;
}

/**
 * The enclosing checkbox's context, for a compound part that cannot work without
 * one.
 *
 * Internal: deliberately not re-exported from `index.ts`. A caller outside the
 * library wants {@link useCheckbox}, whose error message names the hook rather
 * than a part.
 */
export function useCheckboxPart(component: string): CheckboxContextValue {
	const context = useCheckboxContext();
	if (!context) {
		throw new Error(`${component} must be rendered inside a <Checkbox>.`);
	}
	return context;
}

/**
 * Supplies the enclosing group's checked list and its shared defaults.
 *
 * A second context rather than a field on the first: a checkbox reads its group
 * to work out what it *is*, and publishes its own context describing what it
 * *became*. One value carrying both would have to exist before it could be
 * computed.
 */
export function CheckboxGroupProvider({
	value,
	children,
}: {
	value: CheckboxGroupContextValue;
	children: ReactNode;
}): ReactElement {
	return <CheckboxGroupContext value={value}>{children}</CheckboxGroupContext>;
}
CheckboxGroupProvider.displayName = "DelacourUI.Checkbox.Group.Provider";

/**
 * The enclosing group's context, or null for a checkbox standing on its own.
 *
 * This is the export the root reads. It is nullable because a checkbox has to
 * work perfectly well alone — a group is a layout and a state owner a caller
 * opts into, not a wrapper anything requires.
 */
export function useCheckboxGroupContext(): CheckboxGroupContextValue | null {
	return use(CheckboxGroupContext);
}

/**
 * Reads the enclosing group's checked list and defaults.
 *
 * For a custom control that has to sit in a group the way a `Checkbox` does.
 * Throws outside one — use {@link useCheckboxGroupContext} where the group is
 * optional, as the checkbox itself does.
 */
export function useCheckboxGroup(): CheckboxGroupContextValue {
	const context = useCheckboxGroupContext();
	if (!context) {
		throw new Error("useCheckboxGroup must be called inside a <Checkbox.Group>.");
	}
	return context;
}

import { Children, type ReactElement, type ReactNode, useCallback, useEffect, useMemo, useRef } from "react";
import { useControllableState } from "@registry/hooks/use-controllable-state";
import { useFieldContext } from "@registry/ui/field/field.context";
import { Pressable, type PressableProps } from "@registry/ui/pressable";
import { type CheckboxContextValue, CheckboxProvider, useCheckboxGroupContext } from "./checkbox.context";
import type { CheckboxLabelProps } from "./checkbox.types";
import {
	type CheckboxAlignment,
	type CheckboxColor,
	type CheckboxSize,
	checkboxVariants,
	resolveCheckboxAxes,
	resolveCheckboxHitSlop,
} from "./checkbox.variants";
import { CheckboxBox } from "./checkbox-box";
import { CheckboxGroup } from "./checkbox-group";
import { CheckboxLabel } from "./checkbox-label";

export type CheckboxProps = Omit<PressableProps, "asChild" | "busy" | "disabled" | "onPress"> & {
	/**
	 * Identifies this box to an enclosing `Checkbox.Group`. Required inside one,
	 * and ignored outside — a lone checkbox holds its own state.
	 */
	value?: string;
	/** Controlled checked state. Ignored inside a `Checkbox.Group`, which owns it. */
	isChecked?: boolean;
	/** Starting state while uncontrolled. */
	defaultChecked?: boolean;
	onCheckedChange?: (isChecked: boolean) => void;
	/**
	 * Draws a dash rather than a tick and reports `mixed` to a screen reader, for
	 * a parent row over children that are only partly selected.
	 */
	isIndeterminate?: boolean;
	/** What a ticked box means. Inherited from a `Checkbox.Group` when unset. */
	color?: CheckboxColor;
	/** Inherited from a `Checkbox.Group` when unset. */
	size?: CheckboxSize;
	/** `end` pushes the box to the far edge and fills the row with the label. */
	alignment?: CheckboxAlignment;
	/** Reports an invalid value. Inherited from a group, then from a `Field`. */
	isInvalid?: boolean;
	/** Blocks the press and fades the row. Inherited from a group, then a `Field`. */
	isDisabled?: boolean;
	children?: ReactNode;
};

function CheckboxRoot({
	value,
	isChecked,
	defaultChecked = false,
	onCheckedChange,
	isIndeterminate = false,
	color,
	size,
	alignment,
	isInvalid,
	isDisabled,
	feedback = "fade",
	haptic = "selection",
	className,
	children,
	...props
}: CheckboxProps): ReactElement {
	const group = useCheckboxGroupContext();
	const field = useFieldContext();

	const axes = resolveCheckboxAxes({
		field: field ?? undefined,
		group: group ?? undefined,
		own: { alignment, color, isDisabled, isInvalid, size },
	});

	// Called unconditionally so hook order never depends on group membership;
	// which state is *read* below is a plain branch. The same shape `Input` uses
	// to share focus with an `Input.Group`.
	const [ownChecked, setOwnChecked] = useControllableState({
		defaultValue: defaultChecked,
		onChange: onCheckedChange,
		value: isChecked,
	});

	const groupValue = group ? requireValue(value) : undefined;
	const checked = group && groupValue !== undefined ? group.checked.includes(groupValue) : ownChecked;

	const toggle = useCallback(() => {
		if (group && groupValue !== undefined) {
			group.toggle(groupValue);
			return;
		}
		setOwnChecked(!checked);
	}, [checked, group, groupValue, setOwnChecked]);

	// Offered to an enclosing `Field` so tapping the label or the description
	// beside the box ticks it. A checkbox in a form is a small square next to a
	// sentence, and the sentence is what people aim at.
	//
	// Registered through a ref-backed trampoline rather than `toggle` itself:
	// `toggle` is a new function every time `checked` changes, and re-registering
	// on each tick would re-render the whole field for nothing.
	const toggleRef = useRef(toggle);
	toggleRef.current = toggle;
	const registerPress = field?.registerPress;
	const stableToggle = useCallback(() => toggleRef.current(), []);

	useEffect(() => {
		if (!registerPress) return;
		registerPress(stableToggle);
		return () => registerPress(null);
	}, [registerPress, stableToggle]);

	const context = useMemo<CheckboxContextValue>(
		() => ({
			alignment: axes.alignment,
			color: axes.color,
			isChecked: checked,
			isDisabled: axes.isDisabled,
			isIndeterminate,
			isInvalid: axes.isInvalid,
			size: axes.size,
		}),
		[axes.alignment, axes.color, axes.isDisabled, axes.isInvalid, axes.size, checked, isIndeterminate]
	);

	const content = useMemo(() => wrapTextChildren(children), [children]);
	// The box draws itself, including everything the fill state changes, so the
	// root is left with the row and nothing else.
	const rootClassName = checkboxVariants(axes).root({ className });

	return (
		<CheckboxProvider value={context}>
			<Pressable
				accessibilityRole="checkbox"
				accessibilityState={{ checked: isIndeterminate ? "mixed" : checked }}
				className={rootClassName}
				disabled={axes.isDisabled}
				feedback={feedback}
				haptic={haptic}
				hitSlop={resolveCheckboxHitSlop({ hasLabel: Children.count(children) > 0, size: axes.size })}
				onPress={toggle}
				{...props}
			>
				<CheckboxBox />
				{content}
			</Pressable>
		</CheckboxProvider>
	);
}

/**
 * The `value` a grouped checkbox is identified by.
 *
 * A checkbox inside a group with nothing to be called cannot be checked, and the
 * group would silently hold a list that never mentions it. Group membership is
 * not visible in the child's props at compile time, so this cannot be a type
 * error — it throws by name instead, the way `useCheckboxPart` does.
 */
function requireValue(value: string | undefined): string {
	if (value === undefined) {
		throw new Error("A <Checkbox> inside a <Checkbox.Group> needs a `value` for the group to track it by.");
	}
	return value;
}

/**
 * Wraps bare text children in a `Checkbox.Label`.
 *
 * React Native cannot render a string outside a `<Text>`, so
 * `<Checkbox>Remember me</Checkbox>` would otherwise crash. Consecutive strings
 * and numbers are collected into a single label rather than one each — the row's
 * gap would otherwise space the parts of one sentence apart, the same rule and
 * the same reason as `Badge`.
 */
function wrapTextChildren(children: ReactNode): ReactNode {
	const items = Children.toArray(children);
	const output: ReactNode[] = [];
	let run: (string | number)[] = [];

	const flushRun = () => {
		if (run.length === 0) return;
		const props: CheckboxLabelProps = { children: run.join("") };
		output.push(<CheckboxLabel key={`label-${output.length}`} {...props} />);
		run = [];
	};

	for (const child of items) {
		if (typeof child === "string" || typeof child === "number") {
			run.push(child);
			continue;
		}
		flushRun();
		output.push(child);
	}
	flushRun();

	return output;
}

/**
 * A box that is ticked or not — on its own, or as one of a group that shares a
 * value list.
 *
 * The root draws the box itself, so `<Checkbox />` is already a complete
 * control. Anything composed inside it lands beside the box and shares its tap
 * target: `<Checkbox.Label>` is the usual thing, and a bare string is wrapped in
 * one automatically.
 *
 * **The whole `Pressable` surface comes through** — `feedback`, `haptic`,
 * `pressedScale`, `onLongPress` and the rest — because the root *is* a
 * `Pressable`. Two defaults differ from a bare one and only two: `fade`, since a
 * spring on a 20pt square reads as a jitter, and a `selection` haptic, since a
 * checkbox is a state toggle and the tick landing is the confirmation. Both are
 * ordinary props, so `haptic={false}` silences it. `onPress` is the one handler
 * that cannot be forwarded — the press *is* the toggle, and `onCheckedChange` is
 * where a side effect goes.
 *
 * State works either way from one hook: pass `isChecked` to control it, or
 * nothing and let it hold its own. Inside a `Checkbox.Group` the group owns it
 * and the box needs a `value` to be tracked by.
 *
 * `isInvalid` and `isDisabled` cascade in from a `Checkbox.Group` and then from
 * a `Field`, so `<Field isInvalid>` reddens the box with nothing said here — and
 * an explicit prop still wins, in either direction.
 *
 * Inside a `Field` the box also hands its toggle back up, so the whole row is
 * the target: tapping a `Field.Label` or the `Field.Description` under it ticks
 * the box. That is what lets a checkbox in a form be a bare `<Checkbox />` with
 * the field naming it, rather than a `Checkbox.Label` repeating the name.
 *
 * @example
 * <Checkbox isChecked={agreed} onCheckedChange={setAgreed}>
 *   <Checkbox.Label>I accept the terms</Checkbox.Label>
 * </Checkbox>
 *
 * @example
 * <Checkbox.Group checked={channels} onChecked={setChannels}>
 *   <Checkbox value="email">Email</Checkbox>
 *   <Checkbox value="sms">SMS</Checkbox>
 * </Checkbox.Group>
 *
 * @example
 * <Checkbox
 *   alignment="end"
 *   color="success"
 *   isIndeterminate={some && !all}
 *   isChecked={all}
 *   onCheckedChange={toggleAll}
 * >
 *   <Checkbox.Label>Select all</Checkbox.Label>
 * </Checkbox>
 */
export const Checkbox = Object.assign(CheckboxRoot, {
	/** The box's text, inside its tap target — tapping the words toggles it. */
	Label: CheckboxLabel,
	/** Owns the checked list for the checkboxes inside it, and their shared axes. */
	Group: CheckboxGroup,
	displayName: "DelacourUI.Checkbox",
});

import type { VariantProps } from "tailwind-variants";
import { tv } from "@registry/lib/tv";
import type { TextColor, TextSize } from "@registry/ui/text/text.variants";

/** What a ticked box means. The same six `Badge` paints, and for the same reason. */
export const CHECKBOX_COLORS = ["default", "primary", "success", "warning", "danger", "info"] as const;

export const CHECKBOX_SIZES = ["sm", "md", "lg"] as const;

/** Which side of its label the box sits on. */
export const CHECKBOX_ALIGNMENTS = ["start", "end"] as const;

export type CheckboxColor = (typeof CHECKBOX_COLORS)[number];
export type CheckboxSize = (typeof CHECKBOX_SIZES)[number];
export type CheckboxAlignment = (typeof CHECKBOX_ALIGNMENTS)[number];

/**
 * Theme token whose value gives the tick its colour.
 *
 * The checkbox's counterpart to `BADGE_FOREGROUND_TOKEN`, and it exists for the
 * same reason: a colour that has to reach an SVG paint prop cannot be a class.
 * Every entry names the `-foreground` of the fill its own `indicator` slot
 * paints, so the glyph and the surface under it are never a shade apart — a test
 * asserts the pair rather than trusting two maps to stay in step.
 */
export const CHECKBOX_GLYPH_TOKEN: Record<CheckboxColor, string> = {
	default: "secondary-foreground",
	primary: "primary-foreground",
	success: "success-foreground",
	warning: "warning-foreground",
	danger: "danger-foreground",
	info: "info-foreground",
};

/** The tick's colour once the box is reporting an invalid value. */
export const CHECKBOX_INVALID_GLYPH_TOKEN = "danger-foreground";

/**
 * Theme token each colour paints its filled surface with.
 *
 * The same value the `indicator` slot names as a `bg-*`, as a token this time,
 * because the border interpolates *to* it and a colour being animated has to be
 * a value rather than a class. A test pins the two against each other.
 *
 * `default` is `secondary` rather than a colour of its own: this theme's
 * `primary` is a near-black, and its neutral fill already exists.
 */
export const CHECKBOX_SURFACE_TOKEN: Record<CheckboxColor, string> = {
	default: "secondary",
	primary: "primary",
	success: "success",
	warning: "warning",
	danger: "danger",
	info: "info",
};

/**
 * The `rounded-*` step the box wears at each size.
 *
 * Named here as well as written into the `box` slot so the fill can be kept
 * concentric with it — see {@link CHECKBOX_FILL_RADIUS}. A test asserts the two
 * still agree.
 */
export const CHECKBOX_RADIUS_STEP: Record<CheckboxSize, "xs" | "sm"> = { sm: "xs", md: "xs", lg: "sm" };

/** Width of the box's border in points — Tailwind's bare `border` utility. */
export const CHECKBOX_BORDER_WIDTH = 1;

/**
 * Corner radius of the animated fill, in points.
 *
 * The box's own radius **minus its border width**, which is the rule for two
 * rounded rectangles to stay concentric. The fill sits inside the border, so its
 * corner has to be exactly that much tighter or the two curves disagree — and
 * they disagree visibly in both directions. Rounder than this and
 * `overflow-hidden` cuts the fill's corners back past the border's, leaving a
 * sliver of the box's own background at each one; squarer, and the fill reads as
 * a sharp-cornered square inside a rounded box for the whole of the animation
 * that matters.
 *
 * A number rather than a `rounded-*` class because no token is 5pt or 7pt, and
 * there should not be one: these are not a scale, they are `--radius-xs` and
 * `--radius-sm` with a border subtracted. `checkbox.variants.test.ts` reads
 * `tokens.css` and asserts exactly that, so retuning a radius fails the build
 * rather than quietly reopening the gap.
 */
export const CHECKBOX_FILL_RADIUS: Record<CheckboxSize, number> = { sm: 5, md: 5, lg: 7 };

/** The border of a box that is not filled — the same chrome a field wears. */
export const CHECKBOX_REST_BORDER_TOKEN = "input";

/** The border, filled or not, once the box is reporting an invalid value. */
export const CHECKBOX_INVALID_BORDER_TOKEN = "danger";

/**
 * Styling for every part of a checkbox.
 *
 * One slotted `tv()` rather than a call per part, so `size` is declared once
 * across a box, the glyph inside it, the row's gap and the step the label asks
 * its preset for. The sibling file is what makes that possible: the slot set is
 * read by files that cannot import each other's roots without closing a cycle.
 *
 * **`color` paints the `indicator`, not the box.** The indicator is an
 * absolute-fill layer that is invisible until the box is ticked, so a colour
 * needs no unchecked branch — an unticked box is `border-input bg-card` at every
 * colour, the same chrome a field wears. That leaves `compoundVariants` holding
 * one cell rather than a thirty-six cell matrix.
 *
 * **The border is not a class at all.** It fades from the field chrome to the
 * fill's own colour as the surface scales out to meet it, which is a value being
 * interpolated rather than a class being swapped. {@link CHECKBOX_SURFACE_TOKEN}
 * and {@link resolveCheckboxBorderTokens} name the two ends; the base keeps
 * `border-input` as the resting appearance the animated style starts from.
 *
 * `overflow-hidden` on the box is load-bearing, not tidiness: the indicator is a
 * square layer under a rounded border, and without it the fill paints its own
 * corners over the box's.
 *
 * `border` sits in the base rather than on the filled branch. A border declared
 * only where it shows would move the glyph inside by a point the moment the box
 * was ticked.
 *
 * **The box reads the shared icon scale, two steps above its own glyph.** It
 * mints no scale of its own: a checkbox is a glyph in a box, both measurements
 * are already on `--spacing-icon-*`, and a private `--spacing-checkbox-*` would
 * be three numbers that have to be retuned in step with three others forever.
 * Two steps is the gap that leaves the tick breathing room — 18/14, 20/16,
 * 24/18 — and a test pins the offset rather than the numbers, so the scale can
 * be retuned without the test becoming a transcript of it.
 *
 * **The `label` slot holds layout and nothing else** — no size, no weight, no
 * colour. `Checkbox.Label` renders the `Text.Label` preset and passes a step and
 * a colour through {@link resolveCheckboxLabelSize} and
 * {@link resolveCheckboxLabelColor}, so the type scale lives in exactly one
 * place. A `text-sm font-medium` here would be a second definition of
 * `Text.Label` that could drift from it — `Field`'s rule, and the reason `Input`
 * ships no label part at all. The `View` slots hold no `text-*` either: a React
 * Native `View` does not cascade colour to a `Text` descendant. See AGENTS.md
 * rule 1.
 *
 * **The row aligns to the top, and the box carries a margin that puts it back.**
 * A wrapped label centred against its own paragraph drifts the box down the side
 * of it instead of leaving it on the first line — the same thing `Input` refuses
 * for a multiline field's decorators. `items-start` fixes that and would break
 * the ordinary single-line case, so each size adds a top margin of half the
 * difference between the label's line box and the box: 20/24/28 against
 * 18/20/24, which is 1pt, 2pt and 2pt. One line then renders exactly as
 * `items-center` did, and every line after it is a bonus rather than a
 * regression.
 *
 * `opacity-50` for a disabled checkbox goes on the **row**, so the label fades
 * with the box it names rather than standing at full strength beside a ghost.
 *
 * Free of React Native imports so it stays unit-testable — `bun test` cannot
 * parse React Native's Flow-typed source. See AGENTS.md.
 */
export const checkboxVariants = tv({
	slots: {
		root: "flex-row items-start",
		box: "items-center justify-center overflow-hidden border border-input bg-card",
		/** The animated fill. Sits under the box's border, and under the tick. */
		indicator: "absolute inset-0 ",
		/**
		 * Clips the tick. Pinned to the box's left edge with an animated width, so
		 * the glyph is revealed across rather than grown into.
		 */
		tick: "absolute inset-y-0 left-0 overflow-hidden",
		/** Holds the glyph at the box's centre while the clip above it moves. */
		tickInner: "h-full items-center justify-center",
		/** Layout only. The treatment is the `Text.Label` preset's. */
		label: "shrink",
		/** Edge length the tick inherits. */
		glyph: "",
		/** `Checkbox.Group`'s column. */
		group: "gap-4",
	},
	variants: {
		// Paints the fill and nothing else — see the note above on why the box
		// needs no unchecked branch per colour.
		color: {
			default: { indicator: "bg-secondary" },
			primary: { indicator: "bg-primary" },
			success: { indicator: "bg-success" },
			warning: { indicator: "bg-warning" },
			danger: { indicator: "bg-danger" },
			info: { indicator: "bg-info" },
		},
		size: {
			// The box's top margin is half the difference between the label's line
			// box and the box itself — 20/24/28 against 18/20/24 — so a one-line
			// label reads as centred and a wrapped one keeps the box on its first
			// line. See the note above the slots.
			// The box and the glyph inside it read the *same* scale, two steps
			// apart — see the note above the slots.
			sm: { root: "gap-2", box: "mt-px size-icon-md rounded-xs", glyph: "size-icon-xs" },
			md: { root: "gap-2.5", box: "mt-0.5 size-icon-lg rounded-xs", glyph: "size-icon-sm" },
			lg: { root: "gap-3", box: "mt-0.5 size-icon-xl rounded-sm", glyph: "size-icon-md" },
		},
		alignment: {
			start: {},
			// `flex-row-reverse` rather than a branch in the JSX: the box is
			// rendered first either way, so the decision stays a class and the whole
			// matrix stays reachable from `bun test`.
			end: { root: "flex-row-reverse", label: "grow" },
		},
		// The empty `false` branches are load-bearing typing, not placeholders.
		// `tv` derives the prop type from the declared keys, so a map with only
		// `true` types the prop as `true` rather than `boolean` and rejects
		// `checkboxVariants({ isFilled })`. See the note in button.variants.ts.
		//
		// Named `isFilled` rather than `isChecked` because checked and
		// indeterminate both paint the surface and only the glyph tells them
		// apart. `resolveCheckboxFilled` is that translation.
		isFilled: { true: {}, false: {} },
		isInvalid: { true: {}, false: {} },
		isDisabled: { true: { root: "opacity-50" }, false: {} },
	},
	compoundVariants: [
		// Invalid outranks the colour on the fill, whether the box is ticked or
		// not. A checkbox that stayed green while its value was rejected would
		// drop the only signal it has, exactly while the value is being corrected
		// — the precedence `Input` sets between invalid and focus.
		//
		// The *border* is not here. It interpolates between two token values as
		// the fill approaches the edge, so it is a style rather than a class —
		// see `resolveCheckboxBorderTokens`.
		{ isInvalid: true, class: { indicator: "bg-danger" } },
	],
	defaultVariants: {
		color: "default",
		size: "md",
		alignment: "start",
		isFilled: false,
		isInvalid: false,
		isDisabled: false,
	},
});

/**
 * [unfilled, filled] for the fill's two tracks, plus the tick's timing.
 *
 * The fill fades and scales **from the centre of the box**. It does not travel:
 * a translation would make the surface arrive from one edge, which reads as a
 * panel sliding in rather than as a box being filled, and there is no direction
 * a checkbox is filled *from*.
 *
 * The tick is not part of that. It is clipped by a container whose width opens
 * from the box's left edge, so the glyph is drawn on rather than faded up —
 * which is what makes ticking look like ticking, and unticking look like the
 * stroke being taken back. `tickDelay` holds it until the surface it is drawn on
 * is most of the way there; starting both at once reads as one blurred event.
 *
 * One shared progress value drives all of it through `interpolate`, so the
 * tracks cannot drift out of step and there is one animation rather than three.
 *
 * Pure data, so a test can pin that every track travels and that the filled end
 * is a finished box rather than something stopped mid-animation.
 */
export const CHECKBOX_INDICATOR_ANIMATION = {
	opacity: [0, 1],
	scale: [0.8, 1],
	/** Fraction of the fill's travel that passes before the tick starts to draw. */
	tickDelay: 0.25,
	/**
	 * Fraction that passes before the border starts taking the fill's colour.
	 *
	 * Later than the tick, because the border should read as the surface
	 * *reaching* it rather than as a second thing changing alongside it. The fill
	 * scales 0.8 → 1, so it is only near the edge in the last of its travel.
	 */
	borderDelay: 0.55,
	durationMs: 140,
} as const;

/**
 * Points of slop that bring a bare box up to the 44pt minimum touch target.
 *
 * New to this package, and deliberate: `Badge.CloseButton` needs none because it
 * sits inside a padded capsule, while a bare `md` checkbox is a 20pt square with
 * nothing around it.
 */
export const CHECKBOX_HIT_SLOP: Record<CheckboxSize, number> = { sm: 13, md: 12, lg: 10 };

/**
 * Whether the box paints its surface.
 *
 * Indeterminate fills exactly as checked does — only the glyph differs, a dash
 * instead of a tick — so the two collapse to one visual state here and the tv()
 * axis is named for that rather than for `checked`.
 *
 * Pure, so the matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveCheckboxFilled({
	isChecked,
	isIndeterminate,
}: {
	isChecked: boolean;
	isIndeterminate: boolean;
}): boolean {
	return isChecked || isIndeterminate;
}

/** The axes a checkbox can take from itself, its group, or the field around it. */
export type CheckboxAxes = {
	color?: CheckboxColor;
	size?: CheckboxSize;
	alignment?: CheckboxAlignment;
	isInvalid?: boolean;
	isDisabled?: boolean;
};

/** What an enclosing `Field` contributes — state only; it has no opinion on colour. */
export type CheckboxFieldAxes = { isInvalid?: boolean; isDisabled?: boolean };

/**
 * The axes a checkbox actually draws with, given the wrappers around it.
 *
 * The ladder is `own ?? group ?? field ?? default`, on every axis, and the
 * middle rung is where this differs from `Input`.
 *
 * `Input`'s ladder puts its group **first**, because `Input.Group` owns the one
 * box a grouped field renders into — a field's own `variant` there would be a
 * second answer to a question already settled. `Checkbox.Group` owns no box. It
 * is a state controller that also carries shared defaults, which makes it the
 * same kind of thing as `Field`: a wrapper a control can override. So "make the
 * group `lg`" and "make this one danger" are different questions, and both get
 * an answer.
 *
 * `??` throughout and never `||`, so an explicit `false` opts a control out of
 * an invalid field rather than reading as an absence.
 *
 * Pure, so the whole ladder is reachable from `bun test`. See AGENTS.md.
 */
export function resolveCheckboxAxes({
	own,
	group,
	field,
}: {
	own: CheckboxAxes;
	group?: CheckboxAxes;
	field?: CheckboxFieldAxes;
}): Required<CheckboxAxes> {
	return {
		color: own.color ?? group?.color ?? "default",
		size: own.size ?? group?.size ?? "md",
		alignment: own.alignment ?? group?.alignment ?? "start",
		isInvalid: own.isInvalid ?? group?.isInvalid ?? field?.isInvalid ?? false,
		isDisabled: own.isDisabled ?? group?.isDisabled ?? field?.isDisabled ?? false,
	};
}

/**
 * The value list a group holds after one entry is toggled.
 *
 * Appends when absent and filters when present, so the order values were checked
 * in survives and a duplicate that somehow got in is cleared rather than halved.
 * Always a new array: React bails out of a re-render on an unchanged reference,
 * so a mutation here would flip the state and leave the screen alone.
 *
 * Pure, so it is reachable from `bun test`. See AGENTS.md.
 */
export function toggleCheckedValue(current: readonly string[], value: string): string[] {
	return current.includes(value) ? current.filter((entry) => entry !== value) : [...current, value];
}

/**
 * The `Text` step `Checkbox.Label` hands its preset.
 *
 * A size, never a class. The checkbox's own step names map onto `TEXT_SIZES`'
 * own, so the two scales stay level without either restating the other.
 *
 * Pure, so it is reachable from `bun test`. See AGENTS.md.
 */
export function resolveCheckboxLabelSize(size: CheckboxSize): TextSize {
	switch (size) {
		case "sm":
			return "sm";
		case "lg":
			return "lg";
		default:
			return "md";
	}
}

/**
 * The `Text` colour `Checkbox.Label` hands its preset.
 *
 * Returning `undefined` is meaningful rather than lazy: `Text`'s colour axis
 * emits nothing when it is not named, so the label falls through to
 * `Text.Label`'s own `text-foreground`. The same contract `resolveFieldTextColor`
 * uses, and it is what lets the label say "leave it alone".
 *
 * Pure, so it is reachable from `bun test`. See AGENTS.md.
 */
export function resolveCheckboxLabelColor(isInvalid: boolean): TextColor | undefined {
	return isInvalid ? "danger" : undefined;
}

/**
 * The slop a checkbox's tap target takes beyond the box itself.
 *
 * Only a bare box gets any. Once there is a label the whole row is the target
 * and is already wide, and slop on top of that would overlap the next row's —
 * making a tap between two checkboxes ambiguous, which is worse than the target
 * being merely adequate.
 *
 * Pure, so it is reachable from `bun test`. See AGENTS.md.
 */
export function resolveCheckboxHitSlop({
	size,
	hasLabel,
}: {
	size: CheckboxSize;
	hasLabel: boolean;
}): number | undefined {
	return hasLabel ? undefined : CHECKBOX_HIT_SLOP[size];
}

/**
 * The two theme tokens a box's border travels between.
 *
 * `rest` is what an unfilled box wears and `active` is what a filled one settles
 * on — the fill's own colour, so the border reads as the surface having reached
 * the edge rather than as an outline that changed on its own.
 *
 * An invalid box returns danger for **both**, so there is nothing to fade: the
 * border is the signal that the value is wrong, and it has to be there before
 * the box is ticked as much as after. That is the same precedence `Input` sets
 * between invalid and focus, expressed as a pair of endpoints instead of a
 * compound variant.
 *
 * Pure, so the whole matrix is reachable from `bun test`. See AGENTS.md.
 */
export function resolveCheckboxBorderTokens({ color, isInvalid }: { color: CheckboxColor; isInvalid: boolean }): {
	rest: string;
	active: string;
} {
	if (isInvalid) {
		return { active: CHECKBOX_INVALID_BORDER_TOKEN, rest: CHECKBOX_INVALID_BORDER_TOKEN };
	}
	return { active: CHECKBOX_SURFACE_TOKEN[color], rest: CHECKBOX_REST_BORDER_TOKEN };
}

export type CheckboxVariantProps = VariantProps<typeof checkboxVariants>;
